"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[43623],{21061:e=>{e.exports=JSON.parse('{"functions":[{"name":"TrySpawn","desc":"Rolls the current biome\'s chance to spawn one debris near a junk that just\\nspawned at `junkPos`. Skips when at the cap, when the train is not streamed\\nin, or when no clear point is found.","params":[{"name":"junkPos","desc":"","lua_type":"Vector3"}],"returns":[],"function_type":"static","source":{"line":158,"path":"src/StarterPlayer/StarterPlayerScripts/DebrisField.luau"}},{"name":"Step","desc":"Moves every live debris by `moveAmount` studs along the junk direction and\\nspins it; debris past `JunkConfig.DESPAWN_DISTANCE` returns to its free list.","params":[{"name":"moveAmount","desc":"","lua_type":"number"},{"name":"dt","desc":"","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":194,"path":"src/StarterPlayer/StarterPlayerScripts/DebrisField.luau"}},{"name":"GetCounts","desc":"Live debris count and total records (live + idle), for checks.","params":[],"returns":[{"desc":"","lua_type":"number"},{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":217,"path":"src/StarterPlayer/StarterPlayerScripts/DebrisField.luau"}}],"properties":[],"types":[],"name":"DebrisField","desc":"Decorative space-wreck debris that floats past the train with the junk.\\nClient-only and purely visual: `JunkController` calls `TrySpawn` for each\\njunk it spawns and `Step` every frame with the shared junk speed. Debris\\nparts have `CanQuery = false`, so GrabHook and weapon rays pass through.\\nNot pooled with `GenericPoolInstance`: that moves only a model\'s root part,\\nwhich tears these multi-part anchored models apart. A plain free list per\\nmodel is used instead, and all live parts move in one `BulkMoveTo` per frame.","realm":["Client"],"source":{"line":15,"path":"src/StarterPlayer/StarterPlayerScripts/DebrisField.luau"}}')}}]);